mapper.update:
UPDATE effects_queue
SET status     = 'running',
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'pending'

UPDATE effects_queue
SET status      = 'pending',
    retry_count = #{retryCount},
    next_run_at = #{nextRunAt}
WHERE id = #{id}

UPDATE effects_queue
SET status = 'failed'
WHERE id = #{id}
